// Prisma schema for ServiceFlow.
// The initial configuration establishes datasource and client generation only.
// Domain models will be added in later SF tasks, in alignment with the approved SPEC.

generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

import { PrismaClient } from "@prisma/client";

import { serverConfig } from "../config";

const globalForPrisma = globalThis as unknown as {
  prisma?: PrismaClient;
};

export const prisma =
  globalForPrisma.prisma ??
  new PrismaClient({
    datasourceUrl: serverConfig.databaseUrl || undefined,
    log: serverConfig.nodeEnv === "development" ? ["query", "error", "warn"] : ["error"],
  });

if (serverConfig.nodeEnv !== "production") {
  globalForPrisma.prisma = prisma;
}

export default prisma;

